package com.fiap.sast.web;
import com.fiap.sast.github.GitHubClient; import com.fiap.sast.parsing.InvalidJavaSourceException; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { private ProblemDetail p(HttpStatus s,String d){var p=ProblemDetail.forStatusAndDetail(s,d);return p;} @ExceptionHandler({IllegalArgumentException.class}) ProblemDetail bad(Exception e){return p(HttpStatus.BAD_REQUEST,e.getMessage());} @ExceptionHandler({NoSuchElementException.class}) ProblemDetail missing(Exception e){return p(HttpStatus.NOT_FOUND,"Recurso não encontrado");} @ExceptionHandler({GitHubClient.RateLimitException.class}) ProblemDetail rate(Exception e){return p(HttpStatus.TOO_MANY_REQUESTS,"Rate limit do GitHub");} @ExceptionHandler({GitHubClient.LimitException.class}) ProblemDetail limit(Exception e){return p(HttpStatus.PAYLOAD_TOO_LARGE,"Limite de análise excedido");} @ExceptionHandler({InvalidJavaSourceException.class,AnalysisController.Unprocessable.class}) ProblemDetail invalid(Exception e){return p(HttpStatus.UNPROCESSABLE_ENTITY,e.getMessage());} @ExceptionHandler(SecurityException.class) ProblemDetail sec(Exception e){return p(HttpStatus.BAD_REQUEST,"Entrada inválida");} }
